// ---- js/reminders.js ----
// Meal reminder timing: which slots are due now. Plain script, no DOM.
(function (root) {
  const SLOTS = ["nonushta", "tushlik", "kechki"];
  const WINDOW_MS = 10 * 60 * 1000;
  const HOUR_MS = 60 * 60 * 1000;
  const DAY_MS = 24 * HOUR_MS;

  // Local wall-clock parts of an instant in a time zone
  function localParts(date, timezone) {
    const fmt = new Intl.DateTimeFormat("en-CA", {
      timeZone: timezone, hourCycle: "h23",
      year: "numeric", month: "2-digit", day: "2-digit",
      hour: "2-digit", minute: "2-digit", second: "2-digit",
    });
    const p = {};
    fmt.formatToParts(date).forEach((x) => { p[x.type] = x.value; });
    return {
      year: +p.year, month: +p.month, day: +p.day,
      hour: +p.hour % 24, minute: +p.minute, second: +p.second,
    };
  }

  // Reminders whose time (meal time minus lead) is in [now - 10 min, now].
  // All maths is on local wall-clock values expressed as UTC milliseconds.
  function due(opts) {
    const { now, timezone, times, leadHours } = opts;
    const lead = Number(leadHours) || 0;
    if (lead <= 0) return [];
    const n = localParts(now, timezone);
    const nowWall = Date.UTC(n.year, n.month - 1, n.day, n.hour, n.minute, n.second);
    const out = [];
    for (const dayOffset of [0, 1]) {
      const dayStart = Date.UTC(n.year, n.month - 1, n.day) + dayOffset * DAY_MS;
      const mealDay = new Date(dayStart).toISOString().slice(0, 10);
      for (const slot of SLOTS) {
        const m = /^(\d{1,2}):(\d{2})$/.exec((times && times[slot]) || "");
        if (!m) continue;
        const mealWall = dayStart + (+m[1]) * HOUR_MS + (+m[2]) * 60000;
        const remindWall = mealWall - lead * HOUR_MS;
        if (remindWall <= nowWall && remindWall > nowWall - WINDOW_MS) {
          out.push({ slot, mealDay, hours: lead });
        }
      }
    }
    return out;
  }

  root.Reminders = { due, localParts, SLOTS };
})(globalThis);

// ---- js/push-logic.js ----
// Pure helpers for the "push" Edge Function (inlined into supabase/functions/push/index.ts). Plain script, no DOM.
// Needs globalThis.Messages and globalThis.Reminders.
(function (root) {
  const DEFAULTS = { breakfast: "08:00", lunch: "13:00", dinner: "19:00", timezone: "Asia/Tashkent" };
  const FRESH_MS = 15 * 60 * 1000;

  // Subscriptions that belong to the notification's recipient (same family, same person).
  function pickRecipients(notification, subscriptions) {
    if (!notification || !notification.recipient_id) return [];
    return (subscriptions || []).filter((s) => s && s.subscription &&
      s.profile_id === notification.recipient_id && s.household_id === notification.household_id);
  }

  // Only recently created notifications are pushed, so old ids can't be replayed.
  function isFresh(notification, now) {
    const t = Date.parse(notification && notification.created_at);
    return Number.isFinite(t) && Math.abs((now || new Date()).getTime() - t) <= FRESH_MS;
  }

  function vibrateFor(type) {
    try { return root.Messages.build(type || "test", {}).vibrate; } catch (e) { return root.Messages.build("test", {}).vibrate; }
  }

  // One tag per notification, so a new push never silently replaces an earlier one.
  // Only meal reminders share a slot tag (a newer reminder for the same meal replaces the old one).
  function tagFor(n) {
    if (n.type === "meal_reminder") return n.tag || "meal_reminder";
    const base = n.type || n.module || "oila";
    return n.id ? base + "-" + n.id : base;
  }

  // notifications row -> sw.js payload {title, body, tag, vibrate, url}
  function payloadFor(n) {
    return {
      title: n.title || "Oila Uchun",
      body: n.body || n.text || "",
      tag: tagFor(n),
      vibrate: vibrateFor(n.type),
      url: n.link || "index.html",
    };
  }

  function validZone(tz) {
    if (!tz) return false;
    try { new Intl.DateTimeFormat("en-US", { timeZone: tz }); return true; } catch (e) { return false; }
  }

  // Due meal reminders -> [{household_id, profile_id, day, slot, notification}]
  // (the first four are the meal_reminders_sent claim; notification is the row to insert).
  // Only people with a lead time > 0 AND at least one phone subscribed (push_subscriptions row).
  function reminderJobs({ households, profiles, settings, meals, subscriptions, now, rand }) {
    const allowed = households ? new Set(households.map((h) => (typeof h === "string" ? h : h.key))) : null;
    const subscribed = new Set((subscriptions || []).filter(Boolean).map((s) => s.household_id + "|" + s.profile_id));
    const byHouse = {};
    (settings || []).forEach((s) => { byHouse[s.household_id] = s; });
    const out = [];
    for (const p of profiles || []) {
      if (allowed && !allowed.has(p.household_id)) continue;
      const lead = Number(p.meal_lead_hours);
      if (!(lead > 0)) continue;
      if (!subscribed.has(p.household_id + "|" + p.id)) continue;
      const s = { ...DEFAULTS };
      const row = byHouse[p.household_id] || {};
      ["breakfast", "lunch", "dinner"].forEach((k) => { if (row[k]) s[k] = row[k]; });
      if (validZone(row.timezone)) s.timezone = row.timezone;
      const due = root.Reminders.due({
        now, timezone: s.timezone, leadHours: lead,
        times: { nonushta: s.breakfast, tushlik: s.lunch, kechki: s.dinner },
      });
      for (const d of due) {
        const meal = (meals || []).find((m) => m.household_id === p.household_id &&
          String(m.day_date).slice(0, 10) === d.mealDay && m.slot === d.slot);
        const m = root.Messages.build("meal_reminder", { slot: d.slot, hours: d.hours, meal: meal ? meal.title : null }, rand);
        out.push({
          household_id: p.household_id, profile_id: p.id, day: d.mealDay, slot: d.slot,
          notification: {
            household_id: p.household_id, recipient_id: p.id, actor_id: null, module: "meals", type: "meal_reminder",
            title: m.title, body: m.body, tag: m.tag, text: m.body, link: "taomlar.html", read: false,
          },
        });
      }
    }
    return out;
  }

  root.PushLogic = { pickRecipients, reminderJobs, payloadFor, isFresh };
})(globalThis);

const { PushLogic } = globalThis;

const CORS = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type, x-family-key",
  "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
};
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const json = (data, status = 200) =>
  new Response(JSON.stringify(data), { status, headers: { ...CORS, "Content-Type": "application/json" } });

const db = createClient(
  Deno.env.get("SUPABASE_URL"),
  Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") || Deno.env.get("SUPABASE_SECRET_KEY"),
  { auth: { persistSession: false, autoRefreshToken: false } },
);

function must({ data, error }) {
  if (error) throw new Error(error.message || String(error));
  return data;
}

// VAPID keys: generated once and kept in push_keys (id = 1).
let keysPromise = null;
function vapidKeys() {
  keysPromise = keysPromise || (async () => {
    let row = must(await db.from("push_keys").select("public_key, private_key").eq("id", 1).maybeSingle());
    if (!row) {
      const k = webpush.generateVAPIDKeys();
      must(await db.from("push_keys").upsert({ id: 1, public_key: k.publicKey, private_key: k.privateKey },
        { onConflict: "id", ignoreDuplicates: true }));
      row = must(await db.from("push_keys").select("public_key, private_key").eq("id", 1).single());
    }
    return { publicKey: row.public_key, privateKey: row.private_key };
  })().catch((e) => { keysPromise = null; throw e; });
  return keysPromise;
}

async function sendNotificationRow(id) {
  const n = must(await db.from("notifications").select("*").eq("id", id).maybeSingle());
  if (!n || !PushLogic.isFresh(n, new Date())) return 0;
  const subs = PushLogic.pickRecipients(n, must(await db.from("push_subscriptions").select("*")
    .eq("household_id", n.household_id).eq("profile_id", n.recipient_id)));
  if (!subs.length) return 0;
  const { publicKey, privateKey } = await vapidKeys();
  const payload = JSON.stringify(PushLogic.payloadFor(n));
  let sent = 0;
  await Promise.all(subs.map(async (s) => {
    try {
      await webpush.sendNotification(s.subscription, payload, {
        vapidDetails: { subject: "mailto:oila@example.com", publicKey, privateKey },
        TTL: 3600,
      });
      sent++;
    } catch (e) {
      if (e && (e.statusCode === 404 || e.statusCode === 410)) {
        await db.from("push_subscriptions").delete().eq("endpoint", s.endpoint);
      } else {
        console.warn("push failed", s.endpoint, e && (e.statusCode || e.message));
      }
    }
  }));
  return sent;
}

// Meal reminders: claim each due one, then insert a notification (its trigger sends the push).
// Only for people with a lead time and at least one subscribed phone.
async function tick() {
  const now = new Date();
  const day = (offset) => new Date(now.getTime() + offset * 86400000).toISOString().slice(0, 10);
  const profiles = must(await db.from("profiles").select("id, household_id, meal_lead_hours").gt("meal_lead_hours", 0));
  if (!profiles.length) return 0;
  const subscriptions = must(await db.from("push_subscriptions").select("household_id, profile_id"));
  if (!subscriptions.length) return 0;
  const settings = must(await db.from("family_settings").select("*"));
  const meals = must(await db.from("meals").select("household_id, day_date, slot, title")
    .gte("day_date", day(-1)).lte("day_date", day(2)));
  const jobs = PushLogic.reminderJobs({ profiles, settings, meals, subscriptions, now });
  let queued = 0;
  for (const j of jobs) {
    const claim = await db.from("meal_reminders_sent")
      .insert({ household_id: j.household_id, profile_id: j.profile_id, day: j.day, slot: j.slot });
    if (claim.error) {
      if (claim.error.code !== "23505") console.warn("claim failed", claim.error.message);
      continue; // already reminded (or could not claim): skip
    }
    const ins = await db.from("notifications").insert(j.notification);
    if (ins.error) console.warn("reminder insert failed", ins.error.message);
    else queued++;
  }
  return queued;
}

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") return new Response(null, { status: 204, headers: CORS });
  try {
    const url = new URL(req.url);
    if (req.method === "GET" && url.searchParams.has("public_key")) {
      return json({ publicKey: (await vapidKeys()).publicKey });
    }
    if (req.method === "POST") {
      const body = await req.json().catch(() => ({}));
      if (body && typeof body === "object" && "notification_id" in body) {
        if (!UUID.test(String(body.notification_id))) return json({ error: "bad_notification_id" }, 400);
        return json({ sent: await sendNotificationRow(body.notification_id) });
      }
      if (body && body.tick === true) return json({ sent: await tick() });
    }
    return json({ error: "bad_request" }, 400);
  } catch (e) {
    console.error(e);
    return json({ error: "server_error" }, 500);
  }
});
